package foo.droo.gex;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class GexPluginTest {

    private static final Gson GSON = new GsonBuilder().create();

    @Test
    public void testMapStateBuying() {
        assertEquals("buying", GexPlugin.mapState(GrandExchangeOfferState.BUYING));
    }

    @Test
    public void testMapStateBought() {
        assertEquals("bought", GexPlugin.mapState(GrandExchangeOfferState.BOUGHT));
    }

    @Test
    public void testMapStateSelling() {
        assertEquals("selling", GexPlugin.mapState(GrandExchangeOfferState.SELLING));
    }

    @Test
    public void testMapStateSold() {
        assertEquals("sold", GexPlugin.mapState(GrandExchangeOfferState.SOLD));
    }

    @Test
    public void testMapStateCancelledBuy() {
        assertEquals("cancelled_buy", GexPlugin.mapState(GrandExchangeOfferState.CANCELLED_BUY));
    }

    @Test
    public void testMapStateCancelledSell() {
        assertEquals("cancelled_sell", GexPlugin.mapState(GrandExchangeOfferState.CANCELLED_SELL));
    }

    @Test
    public void testMapStateEmpty() {
        assertEquals("empty", GexPlugin.mapState(GrandExchangeOfferState.EMPTY));
    }

    // shouldNotifyStall tests

    @Test
    public void testShouldNotifyStallAboveThreshold() {
        assertTrue(GexPlugin.shouldNotifyStall(150.0, 120));
    }

    @Test
    public void testShouldNotifyStallBelowThreshold() {
        assertFalse(GexPlugin.shouldNotifyStall(60.0, 120));
    }

    @Test
    public void testShouldNotifyStallExactThreshold() {
        assertTrue(GexPlugin.shouldNotifyStall(120.0, 120));
    }

    @Test
    public void testShouldNotifyStallZeroThreshold() {
        assertTrue(GexPlugin.shouldNotifyStall(0.0, 0));
    }

    // shouldNotifyHighValue tests

    @Test
    public void testShouldNotifyHighValueMeetsBoth() {
        assertTrue(GexPlugin.shouldNotifyHighValue(15000, 85.0, 10000, 70));
    }

    @Test
    public void testShouldNotifyHighValueMarginTooLow() {
        assertFalse(GexPlugin.shouldNotifyHighValue(5000, 85.0, 10000, 70));
    }

    @Test
    public void testShouldNotifyHighValueConfidenceTooLow() {
        assertFalse(GexPlugin.shouldNotifyHighValue(15000, 50.0, 10000, 70));
    }

    @Test
    public void testShouldNotifyHighValueExactThresholds() {
        assertTrue(GexPlugin.shouldNotifyHighValue(10000, 70.0, 10000, 70));
    }

    // parseFillCurveResponse tests

    @Test
    public void testParseFillCurveResponseValid() {
        String json = "{\"data\":{\"item_id\":440,\"item_name\":\"Iron ore\",\"curves\":[{"
                + "\"offer_type\":\"buy\","
                + "\"aggregate_by_hour\":{\"10\":{\"avg\":120.5,\"median\":90.0,\"p90\":300.0,\"samples\":15}},"
                + "\"daily_grid\":[{\"day_of_week\":6,\"hours\":{\"10\":{\"avg\":80.0,\"median\":60.0,\"p90\":200.0,\"samples\":5}}}]"
                + "}]}}";

        FillCurveCache cache = new FillCurveCache(GSON);
        FillCurveCache.FillCurveData data = cache.parseFillCurveResponse(json);

        assertNotNull(data);
        assertNotNull(data.aggregateByHour);
        assertEquals(1, data.aggregateByHour.size());
        assertEquals(90.0, data.aggregateByHour.get(10).get("median").doubleValue(), 0.01);

        assertNotNull(data.dailyGrid);
        assertEquals(1, data.dailyGrid.size());
        assertNotNull(data.dailyGrid.get(6));
        assertEquals(60.0, data.dailyGrid.get(6).get(10).get("median").doubleValue(), 0.01);
    }

    @Test
    public void testParseFillCurveResponseEmptyCurves() {
        String json = "{\"data\":{\"item_id\":440,\"item_name\":\"Iron ore\",\"curves\":[]}}";

        FillCurveCache cache = new FillCurveCache(GSON);
        FillCurveCache.FillCurveData data = cache.parseFillCurveResponse(json);
        assertNull(data);
    }

    @Test
    public void testParseFillCurveResponseInvalid() {
        FillCurveCache cache = new FillCurveCache(GSON);
        FillCurveCache.FillCurveData data = cache.parseFillCurveResponse("not json");
        assertNull(data);
    }

    // resolveDayAwareEta tests

    @Test
    public void testDayAwareEtaPrefersDaySpecific() {
        // Build a cache with day-specific data for current day/hour
        FillCurveCache cache = new FillCurveCache(GSON);

        Map<Integer, Map<String, Number>> aggByHour = new HashMap<>();
        Map<String, Number> aggStats = new HashMap<>();
        aggStats.put("median", 300.0); // 5 min aggregate
        // Populate for all hours so test works regardless of current time
        for (int h = 0; h < 24; h++) {
            aggByHour.put(h, aggStats);
        }

        Map<Integer, Map<Integer, Map<String, Number>>> dailyGrid = new HashMap<>();
        Map<String, Number> dayStats = new HashMap<>();
        dayStats.put("median", 120.0); // 2 min day-specific

        // Put data for all days and hours so we always hit
        for (int d = 1; d <= 7; d++) {
            Map<Integer, Map<String, Number>> dayHours = new HashMap<>();
            for (int h = 0; h < 24; h++) {
                dayHours.put(h, dayStats);
            }
            dailyGrid.put(d, dayHours);
        }

        FillCurveCache.FillCurveData curveData = new FillCurveCache.FillCurveData(aggByHour, dailyGrid);
        cache.put(440, curveData);

        // resolveDayAwareEta uses LocalDateTime.now() internally
        // The test validates the function doesn't crash and returns a reasonable value
        double[] result = GexPlugin.resolveDayAwareEta(440, 10.0, cache, true);

        // Should use day-specific 120s = 2.0 min since we have data for all hours/days
        assertEquals(2.0, result[0], 0.01);
        assertTrue(result[1] >= 1 && result[1] <= 7); // dayOfWeek should be 1-7
    }

    @Test
    public void testDayAwareEtaDisabledReturnsPrediction() {
        FillCurveCache cache = new FillCurveCache(GSON);

        double[] result = GexPlugin.resolveDayAwareEta(440, 5.0, cache, false);

        assertEquals(5.0, result[0], 0.01);
        assertEquals(0.0, result[1], 0.01);
    }

    @Test
    public void testDayAwareEtaFallsBackWithNoCache() {
        FillCurveCache cache = new FillCurveCache(GSON);

        double[] result = GexPlugin.resolveDayAwareEta(440, 7.5, cache, true);

        assertEquals(7.5, result[0], 0.01);
        assertEquals(0.0, result[1], 0.01);
    }

    @Test
    public void testDayAwareEtaExpiredCacheFallsBack() {
        // Use short TTL cache to test expiration
        FillCurveCache cache = new FillCurveCache(GSON, 1); // 1ms TTL

        Map<Integer, Map<String, Number>> aggByHour = new HashMap<>();
        Map<Integer, Map<Integer, Map<String, Number>>> dailyGrid = new HashMap<>();
        FillCurveCache.FillCurveData curveData = new FillCurveCache.FillCurveData(aggByHour, dailyGrid);
        cache.put(440, curveData);

        // Wait for cache to expire
        try { Thread.sleep(10); } catch (InterruptedException ignored) {}

        double[] result = GexPlugin.resolveDayAwareEta(440, 3.0, cache, true);

        assertEquals(3.0, result[0], 0.01);
        assertEquals(0.0, result[1], 0.01);
    }

    // dayAbbreviation tests

    @Test
    public void testDayAbbreviations() {
        assertEquals("Mon", GexPlugin.dayAbbreviation(1));
        assertEquals("Tue", GexPlugin.dayAbbreviation(2));
        assertEquals("Wed", GexPlugin.dayAbbreviation(3));
        assertEquals("Thu", GexPlugin.dayAbbreviation(4));
        assertEquals("Fri", GexPlugin.dayAbbreviation(5));
        assertEquals("Sat", GexPlugin.dayAbbreviation(6));
        assertEquals("Sun", GexPlugin.dayAbbreviation(7));
        assertEquals("", GexPlugin.dayAbbreviation(0));
    }
}

package foo.droo.gex;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.zip.GZIPInputStream;

import static org.junit.Assert.*;

/**
 * Tests for network layer functionality: URL construction, request building,
 * batch serialization, and retry logic.
 */
public class NetworkLayerTest {

    private static final Gson GSON = new GsonBuilder().create();
    private MockWebServer mockServer;

    @Before
    public void setUp() throws IOException {
        mockServer = new MockWebServer();
        mockServer.start();
    }

    @After
    public void tearDown() throws IOException {
        mockServer.shutdown();
    }

    // ============ buildEndpointUrl tests ============

    @Test
    public void testBuildEndpointUrlPredict() {
        String base = "https://gex.droo.foo/api/v1/slots";
        String result = GexApiClient.buildEndpointUrl(base, "/api/v1/predict");

        assertEquals("https://gex.droo.foo/api/v1/predict", result);
    }

    @Test
    public void testBuildEndpointUrlBatch() {
        String base = "https://gex.droo.foo/api/v1/slots";
        String result = GexApiClient.buildEndpointUrl(base, "/api/v1/slots/batch");

        assertEquals("https://gex.droo.foo/api/v1/slots/batch", result);
    }

    @Test
    public void testBuildEndpointUrlFillCurves() {
        String base = "https://gex.droo.foo/api/v1/slots";
        String result = GexApiClient.buildEndpointUrl(base, "/api/v1/items/440/fill-curves?offer_type=buy");

        assertEquals("https://gex.droo.foo/api/v1/items/440/fill-curves?offer_type=buy", result);
    }

    @Test
    public void testBuildEndpointUrlLocalhost() {
        String base = "http://localhost:4000/api/v1/slots";
        String result = GexApiClient.buildEndpointUrl(base, "/api/v1/predict");

        assertEquals("http://localhost:4000/api/v1/predict", result);
    }

    @Test
    public void testBuildEndpointUrlWithPort() {
        String base = "https://gex.droo.foo:8443/api/v1/slots";
        String result = GexApiClient.buildEndpointUrl(base, "/api/v1/predict");

        assertEquals("https://gex.droo.foo:8443/api/v1/predict", result);
    }

    @Test
    public void testBuildEndpointUrlNullBase() {
        String result = GexApiClient.buildEndpointUrl(null, "/api/v1/predict");
        assertNull(result);
    }

    @Test
    public void testBuildEndpointUrlEmptyBase() {
        String result = GexApiClient.buildEndpointUrl("", "/api/v1/predict");
        assertNull(result);
    }

    @Test
    public void testBuildEndpointUrlInvalidUrl() {
        // Should fall back to string manipulation
        String base = "not-a-valid-url/api/v1/slots";
        String result = GexApiClient.buildEndpointUrl(base, "/api/v1/predict");

        // Falls back to string manipulation, finds /api/ and replaces
        assertEquals("not-a-valid-url/api/v1/predict", result);
    }

    // ============ Batch payload serialization tests ============

    @Test
    public void testBatchPayloadStructure() {
        List<Map<String, Object>> events = new ArrayList<>();

        Map<String, Object> event1 = new HashMap<>();
        event1.put("account_hash", "abc123");
        event1.put("event_type", "offer_update");
        event1.put("timestamp", "2026-02-21T12:00:00Z");

        Map<String, Object> slot1 = new HashMap<>();
        slot1.put("index", 0);
        slot1.put("item_id", 440);
        slot1.put("offer_type", "buy");
        slot1.put("price", 150);
        slot1.put("quantity_total", 1000);
        slot1.put("quantity_filled", 500);
        slot1.put("state", "buying");
        slot1.put("sequence", 1L);
        event1.put("slot", slot1);

        events.add(event1);

        Map<String, Object> batchPayload = new HashMap<>();
        batchPayload.put("events", events);

        String json = GSON.toJson(batchPayload);

        // Verify structure
        assertTrue(json.contains("\"events\""));
        assertTrue(json.contains("\"account_hash\":\"abc123\""));
        assertTrue(json.contains("\"item_id\":440"));
        assertTrue(json.contains("\"sequence\":1"));
    }

    @Test
    public void testBatchPayloadMultipleEvents() {
        List<Map<String, Object>> events = new ArrayList<>();

        for (int i = 0; i < 3; i++) {
            Map<String, Object> event = new HashMap<>();
            event.put("account_hash", "hash" + i);
            event.put("event_type", "heartbeat");

            Map<String, Object> slot = new HashMap<>();
            slot.put("index", i);
            slot.put("item_id", 440 + i);
            event.put("slot", slot);

            events.add(event);
        }

        Map<String, Object> batchPayload = new HashMap<>();
        batchPayload.put("events", events);

        String json = GSON.toJson(batchPayload);

        // Count occurrences of account_hash (should be 3)
        int count = json.split("account_hash").length - 1;
        assertEquals(3, count);
    }

    // ============ Retry delay pattern tests ============

    @Test
    public void testRetryDelayPattern() {
        int[] delays = {1000, 2000, 4000, 8000};

        // Verify exponential backoff pattern
        assertEquals(1000, delays[0]);
        assertEquals(2000, delays[1]);
        assertEquals(4000, delays[2]);
        assertEquals(8000, delays[3]);

        // Verify each delay is double the previous
        for (int i = 1; i < delays.length; i++) {
            assertEquals(delays[i - 1] * 2, delays[i]);
        }
    }

    @Test
    public void testRetryDelayBounds() {
        int[] delays = {1000, 2000, 4000, 8000};
        int maxRetries = 4;

        // Test that accessing delays with attempt >= maxRetries uses last delay
        for (int attempt = 0; attempt < maxRetries + 2; attempt++) {
            int delay = delays[Math.min(attempt, delays.length - 1)];

            if (attempt < delays.length) {
                assertEquals(delays[attempt], delay);
            } else {
                assertEquals(delays[delays.length - 1], delay);
            }
        }
    }

    // ============ GZIP decompression helper for verification ============

    private String decompressGzip(byte[] compressed) throws IOException {
        try (GZIPInputStream gis = new GZIPInputStream(new ByteArrayInputStream(compressed))) {
            return new String(gis.readAllBytes(), StandardCharsets.UTF_8);
        }
    }

    // ============ Response parsing edge cases ============

    @Test
    public void testParsePredictionsResponseEmpty() {
        String json = "{\"predictions\":[]}";
        // This should not throw and should handle empty list gracefully
        Map<String, Object> data = GSON.fromJson(json, Map.class);
        assertNotNull(data);
        assertTrue(data.containsKey("predictions"));
    }

    @Test
    public void testParsePredictionsResponseMissingPredictions() {
        String json = "{\"daily_pnl\":\"10.5K\"}";
        Map<String, Object> data = GSON.fromJson(json, Map.class);
        assertNotNull(data);
        assertNull(data.get("predictions"));
    }

    @Test
    public void testParsePredictionsResponseMalformed() {
        String json = "{\"predictions\": \"not an array\"}";
        Map<String, Object> data = GSON.fromJson(json, Map.class);
        assertNotNull(data);
        // predictions is a string, not a list
        assertFalse(data.get("predictions") instanceof List);
    }

    // ============ Idempotency key format tests ============

    @Test
    public void testIdempotencyKeyFormat() {
        // Idempotency key should be 16 hex characters (8 bytes of SHA-256)
        String input = "12345:0:440:500:BUYING:2026-02-21T12:00:00";
        // Simulate what generateIdempotencyKey does
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 8; i++) {
                sb.append(String.format("%02x", hash[i]));
            }
            String key = sb.toString();

            assertEquals(16, key.length());
            assertTrue(key.matches("[0-9a-f]{16}"));
        } catch (Exception e) {
            fail("SHA-256 should be available");
        }
    }

    // ============ Queue behavior tests ============

    @Test
    public void testQueueBoundedCapacity() {
        // LinkedBlockingQueue with capacity 100
        java.util.concurrent.LinkedBlockingQueue<Integer> queue =
                new java.util.concurrent.LinkedBlockingQueue<>(100);

        // Fill to capacity
        for (int i = 0; i < 100; i++) {
            assertTrue(queue.offer(i));
        }

        // Queue is full, offer should return false
        assertFalse(queue.offer(100));

        // After removing one, offer should succeed
        queue.poll();
        assertTrue(queue.offer(100));
    }

    @Test
    public void testQueueFifoEviction() {
        java.util.concurrent.LinkedBlockingQueue<Integer> queue =
                new java.util.concurrent.LinkedBlockingQueue<>(3);

        queue.offer(1);
        queue.offer(2);
        queue.offer(3);

        // Simulate FIFO eviction: poll oldest, then offer new
        while (!queue.offer(4)) {
            Integer evicted = queue.poll();
            assertEquals(Integer.valueOf(1), evicted);
        }

        // Queue should now contain 2, 3, 4
        assertEquals(Integer.valueOf(2), queue.poll());
        assertEquals(Integer.valueOf(3), queue.poll());
        assertEquals(Integer.valueOf(4), queue.poll());
    }

    // ============ Delta encoding tests ============

    @Test
    public void testHeartbeatStateKeyFormat() {
        // Heartbeat state key format: slot:itemId:quantitySold:quantityTotal:price:state
        String stateKey = String.format("%d:%d:%d:%d:%d:%s",
            0, 440, 500, 1000, 150, "BUYING");

        assertEquals("0:440:500:1000:150:BUYING", stateKey);
    }

    @Test
    public void testHeartbeatStateKeyDifferentQuantity() {
        String state1 = String.format("%d:%d:%d:%d:%d:%s", 0, 440, 500, 1000, 150, "BUYING");
        String state2 = String.format("%d:%d:%d:%d:%d:%s", 0, 440, 600, 1000, 150, "BUYING");

        // States should be different when quantity changes
        assertNotEquals(state1, state2);
    }

    @Test
    public void testHeartbeatStateKeySameState() {
        String state1 = String.format("%d:%d:%d:%d:%d:%s", 0, 440, 500, 1000, 150, "BUYING");
        String state2 = String.format("%d:%d:%d:%d:%d:%s", 0, 440, 500, 1000, 150, "BUYING");

        // Same state should be equal
        assertEquals(state1, state2);
    }

    @Test
    public void testDeltaEncodingWithMap() {
        Map<Integer, String> lastHeartbeatStates = new ConcurrentHashMap<>();

        // First heartbeat for slot 0
        String state1 = "0:440:0:1000:150:BUYING";
        assertNull(lastHeartbeatStates.put(0, state1));

        // Same state - should not trigger send (equals check returns true)
        String state2 = "0:440:0:1000:150:BUYING";
        assertEquals(state1, state2);
        assertTrue(state2.equals(lastHeartbeatStates.get(0)));

        // Changed state - should trigger send
        String state3 = "0:440:100:1000:150:BUYING";
        assertFalse(state3.equals(lastHeartbeatStates.get(0)));

        // Update tracked state
        lastHeartbeatStates.put(0, state3);
        assertEquals(state3, lastHeartbeatStates.get(0));
    }

    @Test
    public void testDeltaEncodingSlotCleared() {
        Map<Integer, String> lastHeartbeatStates = new ConcurrentHashMap<>();

        // Add state for slot 0
        lastHeartbeatStates.put(0, "0:440:500:1000:150:BUYING");
        assertTrue(lastHeartbeatStates.containsKey(0));

        // Remove state when slot becomes empty
        String removed = lastHeartbeatStates.remove(0);
        assertNotNull(removed);
        assertFalse(lastHeartbeatStates.containsKey(0));

        // Second removal returns null (already cleared)
        assertNull(lastHeartbeatStates.remove(0));
    }
}

package foo.droo.gex;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class GpFormatterTest {

    @Test
    public void testZero() {
        assertEquals("+0", GpFormatter.format(0));
    }

    @Test
    public void testSmallPositive() {
        assertEquals("+500", GpFormatter.format(500));
    }

    @Test
    public void testSmallNegative() {
        assertEquals("-999", GpFormatter.format(-999));
    }

    @Test
    public void testThousands() {
        assertEquals("+1.0K", GpFormatter.format(1_000));
        assertEquals("+52.3K", GpFormatter.format(52_300));
        assertEquals("-10.5K", GpFormatter.format(-10_500));
    }

    @Test
    public void testMillions() {
        assertEquals("+1.0M", GpFormatter.format(1_000_000));
        assertEquals("+3.5M", GpFormatter.format(3_500_000));
        assertEquals("-2.1M", GpFormatter.format(-2_100_000));
    }

    @Test
    public void testBoundaries() {
        assertEquals("+999", GpFormatter.format(999));
        assertEquals("+1.0K", GpFormatter.format(1_000));
        assertEquals("+1000.0K", GpFormatter.format(999_999));
        assertEquals("+1.0M", GpFormatter.format(1_000_000));
    }
}

package foo.droo.gex;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.net.MalformedURLException;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.zip.GZIPOutputStream;

import static java.util.concurrent.TimeUnit.SECONDS;

/**
 * HTTP client for GEX API communication.
 * Handles request building, gzip compression, retry logic, and endpoint construction.
 */
@Slf4j
public class GexApiClient {

    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
    private static final MediaType JSON_GZIP = MediaType.parse("application/json");

    private static final int MAX_RETRY_ATTEMPTS = 4;
    private static final int[] RETRY_DELAYS_MS = {1000, 2000, 4000, 8000};

    // Explicit timeouts to prevent hanging on unresponsive server
    private static final int CONNECT_TIMEOUT_SECONDS = 5;
    private static final int READ_TIMEOUT_SECONDS = 10;
    private static final int WRITE_TIMEOUT_SECONDS = 10;

    // Rate limiting
    private static final long DEFAULT_RATE_LIMIT_COOLDOWN_MS = 60_000; // 1 minute default
    private static final long MAX_RATE_LIMIT_COOLDOWN_MS = 300_000;    // 5 minutes max
    private volatile long rateLimitedUntil = 0;
    private volatile long currentCooldownMs = DEFAULT_RATE_LIMIT_COOLDOWN_MS;

    private final OkHttpClient httpClient;
    private final ScheduledExecutorService executor;
    private final GexConfig config;
    private final Gson gson;

    public interface ConnectionListener {
        void onConnectionStatusChanged(boolean connected);
    }

    private ConnectionListener connectionListener;

    public GexApiClient(OkHttpClient httpClient, ScheduledExecutorService executor, GexConfig config, Gson gson) {
        // Configure client with explicit timeouts
        this.httpClient = httpClient.newBuilder()
            .connectTimeout(CONNECT_TIMEOUT_SECONDS, SECONDS)
            .readTimeout(READ_TIMEOUT_SECONDS, SECONDS)
            .writeTimeout(WRITE_TIMEOUT_SECONDS, SECONDS)
            .build();
        this.executor = executor;
        this.config = config;
        this.gson = gson;
    }

    public void setConnectionListener(ConnectionListener listener) {
        this.connectionListener = listener;
    }

    /**
     * Check if we're currently rate limited.
     */
    public boolean isRateLimited() {
        return System.currentTimeMillis() < rateLimitedUntil;
    }

    /**
     * Get remaining rate limit cooldown in milliseconds.
     */
    public long getRateLimitRemainingMs() {
        long remaining = rateLimitedUntil - System.currentTimeMillis();
        return Math.max(0, remaining);
    }

    /**
     * Handle a 429 rate limit response.
     * Parses Retry-After header if present, otherwise uses exponential backoff.
     */
    private void handleRateLimit(Response response) {
        String retryAfter = response.header("Retry-After");
        long cooldownMs;

        if (retryAfter != null) {
            try {
                // Retry-After can be seconds
                cooldownMs = Long.parseLong(retryAfter) * 1000;
            } catch (NumberFormatException e) {
                cooldownMs = currentCooldownMs;
            }
        } else {
            // Exponential backoff
            cooldownMs = currentCooldownMs;
            currentCooldownMs = Math.min(currentCooldownMs * 2, MAX_RATE_LIMIT_COOLDOWN_MS);
        }

        rateLimitedUntil = System.currentTimeMillis() + cooldownMs;
        log.warn("Rate limited by server, backing off for {}s", cooldownMs / 1000);
    }

    /**
     * Reset rate limit cooldown after successful request.
     */
    private void resetRateLimitCooldown() {
        currentCooldownMs = DEFAULT_RATE_LIMIT_COOLDOWN_MS;
    }

    /**
     * Sends a batch of events to the API with gzip compression and retry logic.
     */
    public void sendBatchAsync(List<Map<String, Object>> batch, Callback callback) {
        if (isRateLimited()) {
            log.debug("Skipping batch send - rate limited for {}s more", getRateLimitRemainingMs() / 1000);
            callback.onFailure(null, new IOException("Rate limited"));
            return;
        }
        sendBatchWithRetry(batch, 0, callback);
    }

    private void sendBatchWithRetry(List<Map<String, Object>> batch, int attempt, Callback callback) {
        String batchEndpoint = buildEndpointUrl(config.apiEndpoint(), "/api/v1/slots/batch");
        if (batchEndpoint == null) {
            callback.onFailure(null, new IOException("Invalid endpoint configuration"));
            return;
        }

        Map<String, Object> batchPayload = new HashMap<>();
        batchPayload.put("events", batch);

        String json = gson.toJson(batchPayload);
        byte[] compressed = compressGzip(json);
        if (compressed == null) {
            compressed = json.getBytes(StandardCharsets.UTF_8);
        }

        Request request = buildRequest(batchEndpoint)
            .post(RequestBody.create(JSON_GZIP, compressed))
            .header("Content-Encoding", "gzip")
            .build();

        httpClient.newCall(request).enqueue(new Callback() {
            @Override
            public void onFailure(Call call, IOException e) {
                log.warn("Failed to send GEX batch: {}", e.getMessage());
                notifyConnectionStatus(false);
                retryBatch(batch, attempt, callback);
            }

            @Override
            public void onResponse(Call call, Response response) {
                try {
                    if (!response.isSuccessful()) {
                        int code = response.code();
                        if (code == 429) {
                            // Rate limited - back off
                            handleRateLimit(response);
                            notifyConnectionStatus(true); // Server is up, just rate limited
                            callback.onFailure(call, new IOException("Rate limited"));
                        } else if (code >= 500 && code < 600) {
                            notifyConnectionStatus(false);
                            retryBatch(batch, attempt, callback);
                        } else {
                            log.warn("GEX batch rejected with {}: {}", code, response.message());
                            notifyConnectionStatus(true);
                            try {
                                callback.onResponse(call, response);
                            } catch (IOException e) {
                                log.debug("Callback error: {}", e.getMessage());
                            }
                        }
                    } else {
                        notifyConnectionStatus(true);
                        resetRateLimitCooldown();
                        try {
                            callback.onResponse(call, response);
                        } catch (IOException e) {
                            log.debug("Callback error: {}", e.getMessage());
                        }
                    }
                } finally {
                    response.close();
                }
            }
        });
    }

    private void retryBatch(List<Map<String, Object>> batch, int attempt, Callback callback) {
        if (attempt >= MAX_RETRY_ATTEMPTS) {
            log.error("GEX batch failed after {} attempts, dropping {} events", MAX_RETRY_ATTEMPTS, batch.size());
            callback.onFailure(null, new IOException("Max retries exceeded"));
            return;
        }

        int delay = RETRY_DELAYS_MS[Math.min(attempt, RETRY_DELAYS_MS.length - 1)];
        executor.schedule(() -> sendBatchWithRetry(batch, attempt + 1, callback), delay, TimeUnit.MILLISECONDS);
    }

