            if ("Connected".equals(status)) {
                statusColor = new Color(76, 175, 80); // Green
            } else if (status != null && status.startsWith("Rate")) {
                statusColor = new Color(255, 152, 0); // Orange for rate limited
            } else {
                statusColor = new Color(244, 67, 54); // Red for disconnected
            }
            statusLabel.setForeground(statusColor);
        });
    }

    /**
     * Update the ML accuracy display.
     * @param accuracyPercent Accuracy percentage (0-100)
     * @param totalPredictions Total number of predictions
     */
    public void updateAccuracy(double accuracyPercent, int totalPredictions) {
        SwingUtilities.invokeLater(() -> {
            if (totalPredictions == 0) {
                accuracyLabel.setText("-");
                accuracyLabel.setForeground(Color.WHITE);
            } else {
                String text = String.format("%.0f%% (%d)", accuracyPercent, totalPredictions);
                accuracyLabel.setText(text);

                // Color by accuracy: green >= 70%, yellow >= 50%, red < 50%
                Color color;
                if (accuracyPercent >= 70) {
                    color = RISK_LOW_COLOR;
                } else if (accuracyPercent >= 50) {
                    color = RISK_MEDIUM_COLOR;
                } else {
                    color = RISK_HIGH_COLOR;
                }
                accuracyLabel.setForeground(color);
            }
        });
    }

    /**
     * Update the market risk indicator.
     * @param riskLevel "low", "medium", or "high"
     * @param dominantRegime "tight", "normal", or "wide"
     */
    public void updateMarketRisk(String riskLevel, String dominantRegime) {
        SwingUtilities.invokeLater(() -> {
            if (riskLevel == null || riskLevel.isEmpty()) {
                riskPanel.setVisible(false);
                return;
            }

            Color riskColor;
            String riskText;
            switch (riskLevel.toLowerCase()) {
                case "high":
                    riskColor = RISK_HIGH_COLOR;
                    riskText = "HIGH";
                    break;
                case "medium":
                    riskColor = RISK_MEDIUM_COLOR;
                    riskText = "MED";
                    break;
                case "low":
                default:
                    riskColor = RISK_LOW_COLOR;
                    riskText = "LOW";
                    break;
            }

            String regimeHint = dominantRegime != null ? " " + dominantRegime.substring(0, 1).toUpperCase() : "";
            riskLabel.setText(riskText + regimeHint);
            riskLabel.setForeground(riskColor);
            riskPanel.setVisible(true);
        });
    }
}

