    @ConfigItem(
        keyName = "apiEndpoint",
        name = "API Endpoint",
        description = "The GEX backend API endpoint for slot telemetry",
        position = 1
    )
    default String apiEndpoint() {
        return "https://gex.droo.foo/api/v1/slots";
    }

    @ConfigItem(
        keyName = "apiKey",
        name = "API Key",
        description = "Your GEX API key for authentication",
        secret = true,
        position = 2
    )
